#!/usr/bin/env python3
"""Run the full matrix. One server container at a time; load generated by oha in a container.

Usage: python3 run.py [--quick] [--only express-1,fastapi-1] [--tasks json,db]
Writes results/results.json as {"results": [...]}.
"""
import argparse, json, subprocess, sys, time
from pathlib import Path

HERE = Path(__file__).parent
OHA_IMAGE = "ghcr.io/hatoo/oha:1.16.0"
SERVERS = ["express-1", "express-n", "fastify-1", "fastify-n", "fastapi-1", "fastapi-n"]
CONCURRENCY = [10, 50, 100, 500]
BODY = json.dumps({"name": "alice", "age": 30, "tags": ["a", "b", "c"]})
TASKS = {
    "json": ("GET", "/json", None),
    "validate": ("POST", "/validate", BODY),
    "db": ("GET", "/db", None),
    "cpu": ("GET", "/cpu", None),
    "io": ("GET", "/io", None),
}


def sh(*a, check=True, capture=True):
    return subprocess.run(a, cwd=HERE, check=check, text=True, capture_output=capture)


def oha(url, method, body, conc, dur):
    cmd = ["docker", "run", "--rm", "--network", "evf_default", "--cpus", "2",
           OHA_IMAGE, "--output-format", "json", "--no-tui", "-z", f"{dur}s", "-c", str(conc), "-m", method]
    if body:
        cmd += ["-H", "content-type: application/json", "-d", body]
    cmd.append(url)
    return json.loads(sh(*cmd).stdout)


def rss_mib(server):
    out = sh("docker", "stats", "--no-stream", "--format", "{{.MemUsage}}", f"evf-{server}-1").stdout
    used = out.split("/")[0].strip()
    val = float(''.join(c for c in used if c.isdigit() or c == '.'))
    return round(val * (1024 if "GiB" in used else 1), 1)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--quick", action="store_true", help="5s runs, 1 repeat, conc 50 only")
    ap.add_argument("--only", default=",".join(SERVERS))
    ap.add_argument("--tasks", default=",".join(TASKS))
    ap.add_argument("--concurrency", default=",".join(map(str, CONCURRENCY)))
    ap.add_argument("--repeats", type=int, default=5)
    ap.add_argument("--duration", type=int, default=60)
    ap.add_argument("--warmup", type=int, default=10)
    a = ap.parse_args()
    dur, warm, reps, concs = a.duration, a.warmup, a.repeats, [int(c) for c in a.concurrency.split(",")]
    if a.quick:
        dur, warm, reps, concs = 5, 2, 1, [50]

    sh("docker", "pull", OHA_IMAGE)
    digest = sh("docker", "image", "inspect", OHA_IMAGE, "--format", "{{index .RepoDigests 0}}").stdout.strip()
    sh("docker", "compose", "up", "-d", "--wait", "postgres")
    out, results = HERE / "results" / "results.json", []

    for server in a.only.split(","):
        sh("docker", "compose", "up", "-d", "--build", "--wait", server)
        t0 = time.time()
        for task in a.tasks.split(","):
            method, path, body = TASKS[task]
            url = f"http://{server}:3000{path}"
            for conc in concs:
                oha(url, method, body, conc, warm)  # warmup, discarded
                for rep in range(reps):
                    r = oha(url, method, body, conc, dur)
                    s, lp = r["summary"], r["latencyPercentiles"]
                    codes = r.get("statusCodeDistribution", {})
                    ok = sum(v for k, v in codes.items() if k.startswith("2"))
                    total = sum(codes.values()) + sum(v for k, v in r.get("errorDistribution", {}).items() if "deadline" not in k)
                    results.append({
                        "provider": server, "task_id": task, "concurrency": conc, "run": rep + 1,
                        "rps": round(s["requestsPerSec"], 1),
                        "p50_ms": round(lp["p50"] * 1000, 2), "p95_ms": round(lp["p95"] * 1000, 2),
                        "p99_ms": round(lp["p99"] * 1000, 2),
                        "error_rate": round(1 - ok / total, 4) if total else 1.0,
                        "rss_mib": rss_mib(server),
                    })
                    print(server, task, conc, rep + 1, results[-1]["rps"], "rps", flush=True)
                    out.write_text(json.dumps({"meta": {"oha": digest, "duration_s": dur,
                                   "warmup_s": warm, "repeats": reps}, "results": results}, indent=1))
        sh("docker", "compose", "stop", server)
    sh("docker", "compose", "down")
    print("wrote", out)


if __name__ == "__main__":
    sys.exit(main())
